//! num_exact ground-truth pin (issue #130, Z-130-EXACT2).
//!
//! The table below is GENERATED from CPython (the oracle IS Python), so
//! these tests are the differential contract in-process:
//! * `div` — 3506 (i64, i64) -> correctly-rounded f64 rows: every edge
//!   pairing of the 2^52/2^53/i64 boundary set plus 3000 seeded random
//!   pairs (seed 20261008), asserted BIT-EXACT against Python
//!   true-division results.
//! * `ord` — 3009 (i64, f64-bits) -> Ordering rows: random pairs, the
//!   +/-0.5 and quarter-offset ties, the issue's filing pair, i64
//!   boundary images, and the infinities.
//!
//! Never hand-edit a row — regenerate from Python if the table needs
//! extending (the generator lives in the PR thread evidence).

use operon::num_exact::{cmp_i64_f64_exact, div_i64_i64_exact};
use std::cmp::Ordering;

fn bits(h: &str) -> f64 {
    f64::from_bits(u64::from_str_radix(h, 16).unwrap())
}

